import React, { useState, useEffect } from "react";
import { useNavigate, Link } from "react-router-dom";
import { 
    requestPasswordResetOTP, 
    verifyPasswordResetOTP, 
    resetPasswordWithOTP 
} from "../../Services/ApiUserService";
import "./ForgotPassword.css";

const ForgotPassword = () => {
    const [step, setStep] = useState(1); // 1: request otp, 2: verify, 3: reset, 4: success
    const [email, setEmail] = useState("");
    const [otp, setOtp] = useState("");
    const [newPassword, setNewPassword] = useState("");
    const [confirmPassword, setConfirmPassword] = useState("");
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState("");
    const [error, setError] = useState("");
    const [countdown, setCountdown] = useState(0);
    
    const navigate = useNavigate();

    // Countdown timer for resend OTP
    useEffect(() => {
        let timer;
        if (countdown > 0) {
            timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        }
        return () => clearTimeout(timer);
    }, [countdown]);

    const handleRequestOtp = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError("");
        setMessage("");
        
        try {
            const res = await requestPasswordResetOTP(email);
            setMessage(res.message || "Đã gửi OTP đến email của bạn. Vui lòng kiểm tra hộp thư.");
            setStep(2);
            setCountdown(180); // 3 minutes countdown
        } catch (err) {
            setError(err.response?.data?.detail || "Có lỗi xảy ra. Vui lòng thử lại.");
        } finally {
            setLoading(false);
        }
    };

    const handleVerifyOtp = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError("");
        setMessage("");
        
        try {
            const res = await verifyPasswordResetOTP(email, otp);
            setMessage(res.message || "OTP hợp lệ. Vui lòng đặt mật khẩu mới.");
            setStep(3);
        } catch (err) {
            setError(err.response?.data?.detail || "OTP không hợp lệ hoặc đã hết hạn.");
        } finally {
            setLoading(false);
        }
    };

    const handleResetPassword = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError("");
        setMessage("");

        // Validate passwords match
        if (newPassword !== confirmPassword) {
            setError("Mật khẩu xác nhận không khớp.");
            setLoading(false);
            return;
        }

        // Validate password strength
        if (newPassword.length < 6) {
            setError("Mật khẩu phải có ít nhất 6 ký tự.");
            setLoading(false);
            return;
        }
        
        try {
            const res = await resetPasswordWithOTP(email, otp, newPassword);
            setMessage(res.message || "Đặt lại mật khẩu thành công!");
            setStep(4);
        } catch (err) {
            setError(err.response?.data?.detail || "Có lỗi xảy ra khi đặt lại mật khẩu.");
        } finally {
            setLoading(false);
        }
    };

    const handleResendOtp = async () => {
        if (countdown > 0) return;
        
        setLoading(true);
        setError("");
        
        try {
            await requestPasswordResetOTP(email);
            setMessage("Đã gửi lại OTP mới đến email của bạn.");
            setCountdown(180);
        } catch (err) {
            setError("Không thể gửi lại OTP. Vui lòng thử lại sau.");
        } finally {
            setLoading(false);
        }
    };

    const formatTime = (seconds) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    return (
        <div className="forgot-password-page container py-5">
            <div className="row justify-content-center">
                <div className="col-md-6">
                    <div className="card border-0 shadow-lg rounded-4">
                        <div className="card-body p-4 p-md-5">
                            {/* Header */}
                            <div className="text-center mb-4">
                                <h2 className="fw-bold" style={{color: "#ff6b35"}}>
                                    Quên mật khẩu
                                </h2>
                                <div className="step-indicator mt-3">
                                    {[1, 2, 3].map((stepNumber) => (
                                        <span 
                                            key={stepNumber}
                                            className={`step ${step >= stepNumber ? 'active' : ''}`}
                                        >
                                            {stepNumber}
                                        </span>
                                    ))}
                                </div>
                            </div>

                            {/* Messages */}
                            {message && (
                                <div className="alert alert-success alert-dismissible fade show">
                                    <i className="fas fa-check-circle me-2"></i>
                                    {message}
                                </div>
                            )}
                            {error && (
                                <div className="alert alert-danger alert-dismissible fade show">
                                    <i className="fas fa-exclamation-triangle me-2"></i>
                                    {error}
                                </div>
                            )}

                            {/* Step 1: Request OTP */}
                            {step === 1 && (
                                <form onSubmit={handleRequestOtp}>
                                    <div className="mb-4">
                                        <label className="form-label fw-semibold">
                                            <i className="fas fa-envelope me-2"></i>
                                            Địa chỉ Email
                                        </label>
                                        <input 
                                            type="email" 
                                            className="form-control form-control-lg" 
                                            value={email} 
                                            onChange={(e) => setEmail(e.target.value)} 
                                            placeholder="Nhập địa chỉ email của bạn"
                                            required 
                                        />
                                        <div className="form-text">
                                            Chúng tôi sẽ gửi mã OTP đến email này để xác minh danh tính.
                                        </div>
                                    </div>
                                    <button 
                                        type="submit"
                                        className="btn btn-lg w-100 text-white fw-bold" 
                                        style={{backgroundColor: "#ff6b35"}} 
                                        disabled={loading}
                                    >
                                        {loading ? (
                                            <>
                                                <span className="spinner-border spinner-border-sm me-2"></span>
                                                Đang gửi...
                                            </>
                                        ) : (
                                            <>
                                                <i className="fas fa-paper-plane me-2"></i>
                                                Gửi mã OTP
                                            </>
                                        )}
                                    </button>
                                </form>
                            )}

                            {/* Step 2: Verify OTP */}
                            {step === 2 && (
                                <form onSubmit={handleVerifyOtp}>
                                    <div className="mb-4">
                                        <label className="form-label fw-semibold">
                                            <i className="fas fa-key me-2"></i>
                                            Mã OTP
                                        </label>
                                        <input 
                                            type="text" 
                                            className="form-control form-control-lg text-center" 
                                            value={otp} 
                                            onChange={(e) => setOtp(e.target.value)} 
                                            placeholder="Nhập mã OTP 6 số"
                                            maxLength="6"
                                            required 
                                        />
                                        <div className="form-text">
                                            Mã OTP đã được gửi đến <strong>{email}</strong>
                                            {countdown > 0 && (
                                                <span className="text-warning">
                                                    {" "}(Hết hạn sau {formatTime(countdown)})
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    <button 
                                        type="submit"
                                        className="btn btn-lg w-100 text-white fw-bold mb-3" 
                                        style={{backgroundColor: "#ff6b35"}} 
                                        disabled={loading}
                                    >
                                        {loading ? (
                                            <>
                                                <span className="spinner-border spinner-border-sm me-2"></span>
                                                Đang xác minh...
                                            </>
                                        ) : (
                                            <>
                                                <i className="fas fa-shield-alt me-2"></i>
                                                Xác minh OTP
                                            </>
                                        )}
                                    </button>

                                    {/* Resend OTP */}
                                    <div className="text-center">
                                        <button 
                                            type="button"
                                            className={`btn btn-link ${countdown > 0 ? 'disabled' : ''}`}
                                            onClick={handleResendOtp}
                                            disabled={countdown > 0 || loading}
                                        >
                                            {countdown > 0 ? (
                                                `Gửi lại sau ${formatTime(countdown)}`
                                            ) : (
                                                <>
                                                    <i className="fas fa-redo me-2"></i>
                                                    Gửi lại mã OTP
                                                </>
                                            )}
                                        </button>
                                    </div>
                                </form>
                            )}

                            {/* Step 3: Reset Password */}
                            {step === 3 && (
                                <form onSubmit={handleResetPassword}>
                                    <div className="mb-3">
                                        <label className="form-label fw-semibold">
                                            <i className="fas fa-lock me-2"></i>
                                            Mật khẩu mới
                                        </label>
                                        <input 
                                            type="password" 
                                            className="form-control form-control-lg" 
                                            value={newPassword} 
                                            onChange={(e) => setNewPassword(e.target.value)} 
                                            placeholder="Nhập mật khẩu mới"
                                            minLength="6"
                                            required 
                                        />
                                    </div>

                                    <div className="mb-4">
                                        <label className="form-label fw-semibold">
                                            <i className="fas fa-lock me-2"></i>
                                            Xác nhận mật khẩu
                                        </label>
                                        <input 
                                            type="password" 
                                            className="form-control form-control-lg" 
                                            value={confirmPassword} 
                                            onChange={(e) => setConfirmPassword(e.target.value)} 
                                            placeholder="Nhập lại mật khẩu mới"
                                            minLength="6"
                                            required 
                                        />
                                        <div className="form-text">
                                            Mật khẩu phải có ít nhất 6 ký tự.
                                        </div>
                                    </div>

                                    <button 
                                        type="submit"
                                        className="btn btn-lg w-100 text-white fw-bold" 
                                        style={{backgroundColor: "#ff6b35"}} 
                                        disabled={loading}
                                    >
                                        {loading ? (
                                            <>
                                                <span className="spinner-border spinner-border-sm me-2"></span>
                                                Đang cập nhật...
                                            </>
                                        ) : (
                                            <>
                                                <i className="fas fa-save me-2"></i>
                                                Đặt lại mật khẩu
                                            </>
                                        )}
                                    </button>
                                </form>
                            )}

                            {/* Step 4: Success */}
                            {step === 4 && (
                                <div className="text-center">
                                    <div className="mb-4">
                                        <i className="fas fa-check-circle fa-5x text-success mb-3"></i>
                                        <h4 className="text-success mb-3">🎉 Hoàn tất!</h4>
                                        <p className="lead">
                                            Mật khẩu của bạn đã được đặt lại thành công.
                                        </p>
                                        <p className="text-muted">
                                            Bạn có thể đăng nhập bằng mật khẩu mới ngay bây giờ.
                                        </p>
                                    </div>

                                    <button 
                                        className="btn btn-lg text-white fw-bold"
                                        style={{backgroundColor: "#ff6b35"}}
                                        onClick={() => navigate('/login')}
                                    >
                                        <i className="fas fa-sign-in-alt me-2"></i>
                                        Đăng nhập ngay
                                    </button>
                                </div>
                            )}

                            {/* Back to login link */}
                            {step < 4 && (
                                <div className="text-center mt-4">
                                    <Link to="/login" className="text-decoration-none">
                                        <i className="fas fa-arrow-left me-2"></i>
                                        Quay lại đăng nhập
                                    </Link>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ForgotPassword;
